/* The appearance preferences use the existing settings record. No journal schema changes. */
export const defaultAppearance=()=>({palette:'sand',uiFont:'cairo',readingFont:'cairo',fontWeight:'500',density:'comfortable',corners:'soft',sidebarTone:'dark',sidebarSide:'right',navigationStyle:'labels',readingWidth:'comfortable',readingLineHeight:'2',customAccent:'#8a593e',customBackground:'#f8f4ed',showWeek:true,showOnThisDay:true,showEmotionHelper:true,showDailyModes:true,reduceMotion:false,defaultMode:'normal'});
const palettes={
 sand:{light:['#f8f4ed','#fffdf9','#302820','#77685b','#e7ddcf','#865438','#f0e3d3','#8a6444'],dark:['#201a17','#2b231e','#f7eadc','#c7b5a3','#4c3b2f','#e3b48d','#3b2e24','#e3b48d'],nav:'#302720'},
 cocoa:{light:['#f4f0ed','#fffcfa','#332824','#78665e','#e4d8d1','#734c3d','#ede1d9','#8e6b54'],dark:['#211b19','#2d2420','#f7eee8','#c6b3a7','#4e3c33','#dfb9a2','#3d2d25','#e2bd9f'],nav:'#2e2420'},
 olive:{light:['#f6f4ea','#fffef8','#313226','#70715d','#dfdfca','#5b6040','#e9eadb','#7b7450'],dark:['#202118','#2a2d20','#f2f1e2','#bec1a5','#474b35','#c4ce99','#363e27','#d3cb99'],nav:'#2c3022'},
 ink:{light:['#f2f4f7','#ffffff','#252f40','#626f82','#dce2eb','#405d83','#e6edf5','#687e97'],dark:['#18202b','#222e3e','#eaf0f9','#aebed3','#3d506b','#a9c7ed','#293d57','#b5c8e0'],nav:'#263347'}
};
const fontNames={cairo:'CairoArabic',plex:'JournalArabic',naskh:'NaskhArabic',system:'Tahoma'};
export function applyAppearance(prefs){
 const root=document.documentElement,dark=root.dataset.theme==='dark',preset=Object.hasOwn(palettes,prefs.palette)?palettes[prefs.palette]:palettes.sand,colors=preset[dark?'dark':'light'];
 ['paper','surface','ink','muted','line','green','soft','gold'].forEach((key,i)=>root.style.setProperty(`--${key}`,colors[i]));
 root.style.setProperty('--nav-bg',preset.nav);root.style.setProperty('--nav-ink','#f4eadf');root.style.setProperty('--on-accent',dark?'#251d17':'#fffdf9');
 if(prefs.palette==='custom'){if(/^#[0-9a-f]{6}$/i.test(prefs.customAccent||''))root.style.setProperty('--green',prefs.customAccent);if(!dark&&/^#[0-9a-f]{6}$/i.test(prefs.customBackground||'')){const bg=prefs.customBackground;root.style.setProperty('--paper',bg);if(onColor(bg)==='#fffdf9'){root.style.setProperty('--surface',mix(bg,'#ffffff',.06));root.style.setProperty('--ink','#fff4e6');root.style.setProperty('--muted',mix(bg,'#ffffff',.65));root.style.setProperty('--line',mix(bg,'#ffffff',.2));root.style.setProperty('--soft',mix(bg,'#ffffff',.1));root.style.setProperty('--gold','#ecd2ad')}};root.style.setProperty('--on-accent',onColor(prefs.customAccent||'#865438'))}
 root.style.setProperty('--ui-font',Object.hasOwn(fontNames,prefs.uiFont)?fontNames[prefs.uiFont]:fontNames.cairo);root.style.setProperty('--reading-font',Object.hasOwn(fontNames,prefs.readingFont)?fontNames[prefs.readingFont]:fontNames.cairo);root.style.setProperty('--ui-weight',['400','500','600'].includes(String(prefs.fontWeight))?prefs.fontWeight:'500');
 root.style.setProperty('--reading-line',String(Math.min(2.6,Math.max(1.6,Number(prefs.readingLineHeight)||2))));root.style.setProperty('--reading-width',prefs.readingWidth==='narrow'?'620px':prefs.readingWidth==='wide'?'940px':'760px');
 for(const [key,choices,fallback] of [['density',['compact','comfortable','spacious'],'comfortable'],['corners',['soft','crisp'],'soft'],['sidebarTone',['dark','light'],'dark'],['sidebarSide',['right','left'],'right'],['navigationStyle',['labels','icons'],'labels']])root.dataset[key]=choices.includes(prefs[key])?prefs[key]:fallback;
 for(const key of ['showWeek','showOnThisDay','showEmotionHelper','showDailyModes'])root.dataset[key]=prefs[key]===false?'false':'true';root.dataset.reduceMotion=prefs.reduceMotion?'true':'false';
 const selected=prefs.palette||'sand';document.querySelectorAll('[data-pref=palette]').forEach(el=>{el.checked=el.value===selected;el.closest('label')?.classList.toggle('selected',el.checked)});
 document.querySelector('meta[name=theme-color]')?.setAttribute('content',colors[5]);
}
function mix(a,b,t){const rgb=hex=>hex.match(/[0-9a-f]{2}/gi).map(v=>parseInt(v,16));const x=rgb(a),y=rgb(b);return '#'+x.map((v,i)=>Math.round(v+(y[i]-v)*t).toString(16).padStart(2,'0')).join('')}
function onColor(hex){const rgb=hex.match(/[0-9a-f]{2}/gi)?.map(v=>parseInt(v,16)/255)||[.2,.2,.2];const lum=rgb.map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return .2126*lum[0]+.7152*lum[1]+.0722*lum[2]>.179?'#251d17':'#fffdf9'}
const select=(p,key,label,choices,fallback)=>`<div class="preference-field"><label for="appearance-${key}">${label}</label><select id="appearance-${key}" data-pref="${key}">${choices.map(([v,t])=>`<option value="${v}" ${String(p[key]||fallback)===String(v)?'selected':''}>${t}</option>`).join('')}</select></div>`;
const toggle=(p,key,label)=>`<label class="preference-toggle"><span>${label}</span><input type="checkbox" data-pref="${key}" ${p[key]!==false?'checked':''}><span class="toggle-track" aria-hidden="true"></span></label>`;
export function appearanceSettings(p,icon){return `<section class="settings-section appearance-section"><div class="settings-section-heading"><span class="settings-symbol">${icon('palette')}</span><div><h2>صمّم مساحتك</h2><p class="muted">كل تغيير يظهر مباشرة، وينحفظ على جهازك.</p></div></div><div class="grid2">${select(p,'theme','المظهر',[['light','فاتح — نهار هادئ'],['dark','داكن — ليل مريح'],['system','حسب الجهاز']],'system')}${select(p,'textSize','حجم النص',[15,17,19,22,25,28].map(n=>[n,`${n} بكسل`]),'17')}</div><h3>ألوان الدفتر</h3><div class="palette-picker">${[['sand','بني ورملي','#865438','#ead8bf'],['cocoa','قهوة وورق','#734c3d','#dec8b9'],['olive','زيتوني دافئ','#5b6040','#d9ddbc'],['ink','حبر أزرق','#405d83','#cad9ed'],['custom','ألواني الخاصة','#8a593e','#f8f4ed']].map(([id,label,a,b])=>`<label class="palette-option ${(p.palette||'sand')===id?'selected':''}"><input type="radio" name="palette" value="${id}" data-pref="palette" ${(p.palette||'sand')===id?'checked':''}><span class="palette-swatches" aria-hidden="true" style="--swatch-a:${a};--swatch-b:${b}"><i></i><i></i></span><strong>${label}</strong>${icon('check')}</label>`).join('')}</div><div class="custom-colors"><label>لون الأفعال الأساسية<input type="color" data-pref="customAccent" value="${/^#[0-9a-f]{6}$/i.test(p.customAccent||'')?p.customAccent:'#865438'}"></label><label>خلفية المظهر الفاتح<input type="color" data-pref="customBackground" value="${/^#[0-9a-f]{6}$/i.test(p.customBackground||'')?p.customBackground:'#f8f4ed'}"></label><small>تُستخدم هذه الألوان عند اختيار «ألواني الخاصة».</small></div><div class="appearance-preview"><span class="eyebrow">معاينة حية</span><h3>تفصيل صغير، ذكرى تبقى.</h3><p>أكتب مثل ما أحچي. My words, my memories.</p><span class="preview-action">هذا هو لون أفعالك</span></div><h3>الخطوط والقراءة</h3><div class="grid2">${select(p,'uiFont','خط الواجهة',[['cairo','Cairo — كايرو'],['plex','IBM Plex Arabic'],['system','خط الجهاز']],'cairo')}${select(p,'readingFont','خط صفحات اليوميات',[['cairo','Cairo — كايرو'],['naskh','Noto Naskh — نسخي'],['plex','IBM Plex Arabic'],['system','خط الجهاز']],'cairo')}${select(p,'fontWeight','وزن خط الواجهة',[['400','خفيف'],['500','متوازن'],['600','واضح']],'500')}${select(p,'readingWidth','عرض القراءة',[['narrow','ضيّق'],['comfortable','مريح'],['wide','واسع']],'comfortable')}${select(p,'readingLineHeight','تباعد أسطر اليوميات',[['1.6','قريب'],['2','مريح'],['2.3','واسع'],['2.6','واسع جدًا']],'2')}</div><h3>ترتيب الواجهة</h3><div class="grid2">${select(p,'density','المسافات',[['compact','مدمجة'],['comfortable','متوازنة'],['spacious','واسعة']],'comfortable')}${select(p,'corners','حواف العناصر',[['soft','ناعمة'],['crisp','مستقيمة']],'soft')}${select(p,'sidebarTone','لون القائمة',[['dark','داكن'],['light','فاتح']],'dark')}${select(p,'sidebarSide','مكان قائمة سطح المكتب',[['right','اليمين'],['left','اليسار']],'right')}${select(p,'navigationStyle','عرض قائمة سطح المكتب',[['labels','أيقونات وعناوين'],['icons','أيقونات فقط']],'labels')}${select(p,'defaultMode','مستوى التدوين الافتراضي',[['quick','تدوين سريع'],['normal','يومي المعتاد'],['deep','تأمل أعمق']],'normal')}</div><h3>ما يظهر في صفحة اليوم</h3><div class="preference-toggles">${toggle(p,'showWeek','أسبوعي، يومًا بيوم')}${toggle(p,'showOnThisDay','في مثل هذا اليوم')}${toggle(p,'showEmotionHelper','مساعدة تسمية الشعور')}${toggle(p,'showDailyModes','اختصارات اليوم الصعب والحلو والعادي')}</div><label class="preference-toggle"><span>تقليل الحركة</span><input type="checkbox" data-pref="reduceMotion" ${p.reduceMotion?'checked':''}><span class="toggle-track" aria-hidden="true"></span></label><button class="ghost" data-action="reset-appearance">${icon('reset')} استعادة المظهر البني والرملي</button></section>`}
